1	import { useState } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	import { useAuth } from "@/hooks/useAuth";
5	import {
6	  Dialog,
7	  DialogContent,
8	  DialogDescription,
9	  DialogHeader,
10	  DialogTitle,
11	  DialogTrigger,
12	} from "@/components/ui/dialog";
13	import { Button } from "@/components/ui/button";
14	import { Input } from "@/components/ui/input";
15	import { Label } from "@/components/ui/label";
16	import { Badge } from "@/components/ui/badge";
17	import { toast } from "sonner";
18	import { Coins, Loader2, ShoppingCart, Crown, Wallet } from "lucide-react";
19	import SubscriptionDialog from "@/components/SubscriptionDialog";
20	
21	interface BuyCreditsDialogProps {
22	  trigger?: React.ReactNode;
23	}
24	
25	const QUICK_AMOUNTS = [5, 10, 25, 50];
26	
27	const BuyCreditsDialog = ({ trigger }: BuyCreditsDialogProps) => {
28	  const { user } = useAuth();
29	  const [open, setOpen] = useState(false);
30	  const [amount, setAmount] = useState("");
31	  const [buying, setBuying] = useState(false);
32	
33	  const { data: config } = useQuery({
34	    queryKey: ["platform_config_topup"],
35	    queryFn: async () => {
36	      const { data, error } = await supabase
37	        .from("platform_config")
38	        .select("payg_per_resume_cost, topup_min_amount")
39	        .limit(1)
40	        .single();
41	      if (error) throw error;
42	      return data as any;
43	    },
44	  });
45	
46	  const perResumeCost = config?.payg_per_resume_cost ?? 0.07;
47	  const minAmount = config?.topup_min_amount ?? 1;
48	  const numericAmount = parseFloat(amount) || 0;
49	  const calculatedCredits = perResumeCost > 0 ? Math.floor(numericAmount / perResumeCost) : 0;
50	  const isValid = numericAmount >= minAmount;
51	
52	  const handleBuy = async () => {
53	    if (!user || !isValid) return;
54	    setBuying(true);
55	
56	    try {
57	      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
58	        body: {
59	          topup_amount: numericAmount,
60	          return_url: `${window.location.origin}/payment/callback`,
61	        },
62	      });
63	
64	      if (error) throw error;
65	
66	      if (!data?.checkout_url) {
67	        toast.error(data?.error || "Failed to create checkout session");
68	        return;
69	      }
70	
71	      window.location.href = data.checkout_url;
72	    } catch (err: any) {
73	      toast.error(err.message);
74	    } finally {
75	      setBuying(false);
76	    }
77	  };
78	
79	  return (
80	    <Dialog open={open} onOpenChange={setOpen}>
81	      <DialogTrigger asChild>
82	        {trigger || (
83	          <Button variant="outline" className="gap-2">
84	            <ShoppingCart className="h-4 w-4" />
85	            Buy Credits
86	          </Button>
87	        )}
88	      </DialogTrigger>
89	      <DialogContent className="sm:max-w-md">
90	        <DialogHeader>
91	          <DialogTitle className="flex items-center gap-2">
92	            <Coins className="h-5 w-5 text-primary" />
93	            Add Credits
94	          </DialogTitle>
95	          <DialogDescription>
96	            Enter any amount to recharge your wallet. Credits never expire.
97	          </DialogDescription>
98	        </DialogHeader>
99	
100	        <div className="space-y-4 pt-2">
101	          {/* Quick amount buttons */}
102	          <div className="flex gap-2 flex-wrap">
103	            {QUICK_AMOUNTS.filter(a => a >= minAmount).map((a) => (
104	              <Button
105	                key={a}
106	                variant={numericAmount === a ? "default" : "outline"}
107	                size="sm"
108	                className="flex-1 min-w-[60px]"
109	                onClick={() => setAmount(String(a))}
110	              >
111	                ${a}
112	              </Button>
113	            ))}
114	          </div>
115	
116	          {/* Amount input */}
117	          <div>
118	            <Label htmlFor="credit-amount" className="text-sm font-medium text-foreground mb-1.5 block">
119	              Custom Amount (USD) <span className="text-destructive">*</span>
120	            </Label>
121	            <div className="relative">
122	              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
123	              <Input
124	                id="credit-amount"
125	                type="number"
126	                step="0.5"
127	                min={minAmount}
128	                placeholder={String(minAmount)}
129	                value={amount}
130	                onChange={(e) => setAmount(e.target.value)}
131	                className="pl-7 text-lg font-semibold"
132	                autoFocus
133	              />
134	            </div>
135	            <p className="text-[11px] text-muted-foreground mt-1">
136	              Minimum: ${minAmount}
137	            </p>
138	          </div>
139	
140	          {/* Credit preview */}
141	          {numericAmount > 0 && (
142	            <div className="rounded-lg bg-accent/50 border border-border p-4 text-center">
143	              <div className="flex items-center justify-center gap-2">
144	                <Wallet className="h-5 w-5 text-primary" />
145	                <span className="text-sm text-muted-foreground">You'll get</span>
146	              </div>
147	              <div className="flex items-center justify-center gap-2 mt-1">
148	                <Badge className="gap-1 text-base px-3 py-1">
149	                  <Coins className="h-4 w-4" />
150	                  {calculatedCredits} credits
151	                </Badge>
152	              </div>
153	              <p className="text-[11px] text-muted-foreground mt-2">
154	                1 credit = 1 resume ranked • ${perResumeCost}/credit
155	              </p>
156	            </div>
157	          )}
158	
159	          {/* Pay button */}
160	          <Button
161	            className="w-full"
162	            size="lg"
163	            onClick={handleBuy}
164	            disabled={buying || !isValid}
165	          >
166	            {buying ? (
167	              <Loader2 className="h-4 w-4 animate-spin mr-2" />
168	            ) : null}
169	            {numericAmount > 0 ? `Pay $${numericAmount.toFixed(2)}` : "Enter an amount"}
170	          </Button>
171	        </div>
172	
173	        {/* Subscription upsell */}
174	        <div className="rounded-lg bg-primary/5 border border-primary/20 px-4 py-3 flex items-center justify-between">
175	          <div className="flex items-center gap-2">
176	            <Crown className="h-4 w-4 text-primary" />
177	            <p className="text-xs font-medium text-foreground">Save more with a subscription plan</p>
178	          </div>
179	          <SubscriptionDialog
180	            trigger={
181	              <Button variant="ghost" size="sm" className="h-7 text-xs text-primary hover:text-primary gap-1">
182	                View Plans →
183	              </Button>
184	            }
185	          />
186	        </div>
187	      </DialogContent>
188	    </Dialog>
189	  );
190	};
191	
192	export default BuyCreditsDialog;
193	
