1	import React from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { useNavigate } from "react-router-dom";
4	import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
5	import { Button } from "@/components/ui/button";
6	import { Separator } from "@/components/ui/separator";
7	import { Database, ChevronDown, AlertTriangle, Plus, Zap, Gift, CreditCard } from "lucide-react";
8	import { cn } from "@/lib/utils";
9	import { useState } from "react";
10	
11	const WalletDropdown = () => {
12	  const { profile } = useAuth();
13	  const navigate = useNavigate();
14	  const [open, setOpen] = useState(false);
15	
16	  const subCredits = profile?.subscription_credits ?? 0;
17	  const topCredits = profile?.topup_credits ?? 0;
18	  const bonusCredits = profile?.bonus_credits ?? 0;
19	  const splitTotal = subCredits + topCredits + bonusCredits;
20	  const legacyCredits = profile?.credits ?? 0;
21	  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
22	  const isLowCredits = totalCredits < 3;
23	  const hasSplitCredits = splitTotal > 0;
24	
25	  return (
26	    <Popover open={open} onOpenChange={setOpen}>
27	      <PopoverTrigger asChild>
28	        <button
29	          className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-1 border transition-all ${
30	            isLowCredits
31	              ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
32	              : "border-border bg-muted/50 text-foreground hover:border-foreground/30 hover:bg-muted focus-visible:ring-ring"
33	          }`}
34	        >
35	          {isLowCredits ? (
36	            <AlertTriangle className="h-4 w-4 shrink-0" />
37	          ) : (
38	            <Database className="h-4 w-4 shrink-0 text-primary" />
39	          )}
40	          <span className="text-sm font-semibold tabular-nums">{totalCredits.toLocaleString()}</span>
41	          <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
42	          <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
43	        </button>
44	      </PopoverTrigger>
45	
46	      <PopoverContent align="end" className="w-72 p-0">
47	        {/* Balance header */}
48	        <div className="px-4 pt-4 pb-3">
49	          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">Credit Balance</p>
50	          <div className="flex items-baseline gap-2 mt-1">
51	            <span className="text-3xl font-bold tabular-nums text-foreground leading-none">
52	              {totalCredits.toLocaleString()}
53	            </span>
54	            <span className="text-xs text-muted-foreground font-medium">credits left</span>
55	          </div>
56	        </div>
57	
58	        {/* Progress bar */}
59	        {hasSplitCredits && totalCredits > 0 && (
60	          <div className="px-4 pb-3">
61	            <div className="h-2 rounded-full bg-muted overflow-hidden flex">
62	              {[
63	                { label: "Monthly", value: subCredits, color: "bg-primary" },
64	                { label: "Top-up", value: topCredits, color: "bg-primary/60" },
65	                { label: "Bonus", value: bonusCredits, color: "bg-amber-400" },
66	              ].map((seg) =>
67	                seg.value > 0 ? (
68	                  <div
69	                    key={seg.label}
70	                    className={cn("h-full first:rounded-l-full last:rounded-r-full", seg.color)}
71	                    style={{ width: `${(seg.value / totalCredits) * 100}%` }}
72	                  />
73	                ) : null
74	              )}
75	            </div>
76	            <div className="flex items-center gap-3 mt-2">
77	              {[
78	                { label: "Monthly", value: subCredits, color: "bg-primary" },
79	                { label: "Top-up", value: topCredits, color: "bg-primary/60" },
80	                { label: "Bonus", value: bonusCredits, color: "bg-amber-400" },
81	              ].map((seg) =>
82	                seg.value > 0 ? (
83	                  <div key={seg.label} className="flex items-center gap-1.5">
84	                    <span className={cn("h-2 w-2 rounded-full", seg.color)} />
85	                    <span className="text-[10px] text-muted-foreground">
86	                      {seg.label} ({seg.value.toLocaleString()})
87	                    </span>
88	                  </div>
89	                ) : null
90	              )}
91	            </div>
92	          </div>
93	        )}
94	
95	        <Separator />
96	
97	        {/* Breakdown rows */}
98	        {hasSplitCredits && (
99	          <div className="px-4 py-3 space-y-2.5">
100	            <CreditRow icon={Zap} label="Subscription" value={subCredits} color="text-primary" />
101	            <CreditRow icon={CreditCard} label="Top-up" value={topCredits} color="text-emerald-500" />
102	            <CreditRow icon={Gift} label="Bonus" value={bonusCredits} color="text-amber-500" />
103	          </div>
104	        )}
105	
106	        {/* Low credits warning */}
107	        {isLowCredits && (
108	          <>
109	            <Separator />
110	            <div className="px-4 py-2.5 bg-destructive/5">
111	              <p className="text-xs text-destructive font-medium">
112	                Running low — top up to keep ranking.
113	              </p>
114	            </div>
115	          </>
116	        )}
117	
118	        {/* Explainer */}
119	        {hasSplitCredits && !isLowCredits && (
120	          <>
121	            <Separator />
122	            <div className="px-4 py-2">
123	              <p className="text-[10px] text-muted-foreground/70 leading-relaxed">
124	                Monthly credits used first. Top-up & bonus never expire.
125	              </p>
126	            </div>
127	          </>
128	        )}
129	
130	        {/* Actions */}
131	        <Separator />
132	        <div className="p-2">
133	          <Button
134	            className="w-full gap-2"
135	            onClick={() => { setOpen(false); navigate("/billing"); }}
136	          >
137	            <Plus className="h-4 w-4" />
138	            Buy Credits
139	          </Button>
140	        </div>
141	      </PopoverContent>
142	    </Popover>
143	  );
144	};
145	
146	function CreditRow({
147	  icon: Icon,
148	  label,
149	  value,
150	  color,
151	}: {
152	  icon: React.ComponentType<{ className?: string }>;
153	  label: string;
154	  value: number;
155	  color: string;
156	}) {
157	  return (
158	    <div className="flex items-center justify-between">
159	      <div className="flex items-center gap-2">
160	        <Icon className={`h-3.5 w-3.5 ${color}`} />
161	        <span className="text-xs text-muted-foreground">{label}</span>
162	      </div>
163	      <span className="text-xs font-semibold tabular-nums text-foreground">{value.toLocaleString()}</span>
164	    </div>
165	  );
166	}
167	
168	export default React.memo(WalletDropdown);
