1	import { useState, useEffect } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { Card, CardContent } from "@/components/ui/card";
4	import { Button } from "@/components/ui/button";
5	import { Badge } from "@/components/ui/badge";
6	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
7	import { User, ShoppingCart, Crown, Zap, ArrowUpRight, AlertTriangle } from "lucide-react";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import BuyCreditsDialog from "@/components/BuyCreditsDialog";
10	import SubscriptionDialog from "@/components/SubscriptionDialog";
11	import { useNavigate } from "react-router-dom";
12	
13	type CreditType = { key: string; color: string; label: string; count: number; desc: string };
14	
15	const CREDIT_TYPES: Omit<CreditType, "count">[] = [
16	  { key: "monthly", color: "hsl(var(--rk-primary))", label: "Monthly", desc: "From your subscription — consumed first." },
17	  { key: "topup", color: "hsl(var(--rk-score-overall))", label: "Top-up", desc: "One-time pack purchase — never expire, used after monthly." },
18	  { key: "bonus", color: "hsl(var(--rk-score-education))", label: "Bonus", desc: "Bonus credits — used last, never expire." },
19	];
20	
21	const AccountInfoCard = ({ showHero = true }: { showHero?: boolean }) => {
22	  const { user, profile } = useAuth();
23	  const navigate = useNavigate();
24	  const [animated, setAnimated] = useState(false);
25	
26	  useEffect(() => {
27	    const t = setTimeout(() => setAnimated(true), 50);
28	    return () => clearTimeout(t);
29	  }, []);
30	
31	  const subCredits = profile?.subscription_credits ?? 0;
32	  const topCredits = profile?.topup_credits ?? 0;
33	  const bonusCredits = profile?.bonus_credits ?? 0;
34	  const splitTotal = subCredits + topCredits + bonusCredits;
35	  const legacyCredits = profile?.credits ?? 0;
36	  const total = splitTotal > 0 ? splitTotal : legacyCredits;
37	  const showLegacy = splitTotal === 0 && legacyCredits > 0;
38	
39	  const plan = profile?.plan ?? "free";
40	  const isPaid = plan !== "free";
41	  const isLow = total < 3;
42	
43	  // Build credit types with counts
44	  const creditTypes: CreditType[] = showLegacy
45	    ? [{ key: "legacy", color: "hsl(var(--rk-primary))", label: "Available", count: legacyCredits, desc: "Your available credits." }]
46	    : CREDIT_TYPES.map((t) => ({
47	        ...t,
48	        count: t.key === "monthly" ? subCredits : t.key === "topup" ? topCredits : bonusCredits,
49	      }));
50	
51	  const activeSegments = creditTypes.filter((t) => t.count > 0);
52	  const activeSource = subCredits > 0 ? "monthly" : topCredits > 0 ? "top-up" : bonusCredits > 0 ? "bonus" : null;
53	
54	
55	  return (
56	    <Card className="overflow-hidden">
57	      {/* Hero banner — only on profile page */}
58	      {showHero && (
59	        <div className="relative bg-gradient-to-br from-primary/10 via-primary/5 to-transparent dark:from-primary/20 dark:via-primary/10 px-6 pt-6 pb-8">
60	          <div className="flex items-start justify-between">
61	            <div className="flex items-center gap-3">
62	              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 ring-2 ring-primary/20">
63	                <User className="h-6 w-6 text-primary" />
64	              </div>
65	              <div>
66	                <p className="text-sm font-medium text-muted-foreground">Welcome back</p>
67	                <p className="text-base font-semibold text-foreground truncate max-w-[220px] sm:max-w-none">
68	                  {user?.email}
69	                </p>
70	              </div>
71	            </div>
72	            <div className="flex items-center gap-2">
73	              <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
74	                {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
75	                {isPaid ? plan : "Pay As You Go"}
76	              </Badge>
77	              <SubscriptionDialog
78	                trigger={
79	                  <Button variant="ghost" size="sm" className="h-7 gap-1 text-xs text-primary hover:text-primary">
80	                    <ArrowUpRight className="h-3 w-3" />
81	                    {isPaid ? "Manage" : "Upgrade"}
82	                  </Button>
83	                }
84	              />
85	            </div>
86	          </div>
87	        </div>
88	      )}
89	
90	      {/* Plan bar — shown when hero is hidden (billing page) */}
91	      {!showHero && (
92	        <div className="px-6 pt-5 pb-0 flex items-center justify-between">
93	          <div className="flex items-center gap-2">
94	            <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
95	              {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
96	              {isPaid ? plan : "Pay As You Go"}
97	            </Badge>
98	          </div>
99	          <SubscriptionDialog
100	            trigger={
101	              <Button variant="outline" size="sm" className="h-7 gap-1.5 text-xs">
102	                <ArrowUpRight className="h-3 w-3" />
103	                {isPaid ? "Manage Plan" : "Upgrade"}
104	              </Button>
105	            }
106	          />
107	        </div>
108	      )}
109	
110	      {/* Credits section */}
111	      <CardContent className="px-6 py-5 space-y-3">
112	        {!profile ? (
113	          <div className="space-y-3">
114	            <div className="flex items-center justify-between">
115	              <Skeleton className="h-4 w-16" />
116	              <Skeleton className="h-7 w-24" />
117	            </div>
118	            <Skeleton className="h-2 w-full rounded-full" />
119	            <div className="flex gap-4">
120	              <Skeleton className="h-3 w-20" />
121	              <Skeleton className="h-3 w-20" />
122	              <Skeleton className="h-3 w-20" />
123	            </div>
124	          </div>
125	        ) : (
126	        <>
127	        {/* Header row */}
128	        <div className="flex items-center justify-between">
129	          <span className="text-sm font-semibold text-foreground">Credits</span>
130	          <div className="flex items-center gap-3">
131	            <span className="text-sm font-semibold text-foreground tabular-nums">
132	              {total}
133	              <span className="text-muted-foreground font-normal ml-1">left</span>
134	            </span>
135	            <BuyCreditsDialog
136	              trigger={
137	                <Button size="sm" variant="outline" className="h-7 gap-1.5 text-xs">
138	                  <ShoppingCart className="h-3 w-3" />
139	                  Top Up
140	                </Button>
141	              }
142	            />
143	          </div>
144	        </div>
145	
146	        {/* Segmented bar */}
147	        <TooltipProvider delayDuration={80}>
148	          <div className="space-y-2">
149	            {/* Bar track */}
150	            <div className="relative h-2 w-full rounded-full bg-muted">
151	              <div className="absolute inset-0 flex gap-[2px]">
152	                {activeSegments.map((seg, i) => {
153	                  const pct = (seg.count / total) * 100;
154	                  return (
155	                    <Tooltip key={seg.key}>
156	                      <TooltipTrigger asChild>
157	                        <div
158	                          className="h-full cursor-pointer transition-all duration-500 ease-out hover:brightness-110"
159	                          style={{
160	                            width: animated ? `${pct}%` : "0%",
161	                            backgroundColor: seg.color,
162	                            transitionDelay: `${i * 100}ms`,
163	                            borderRadius:
164	                              activeSegments.length === 1
165	                                ? "9999px"
166	                                : i === 0
167	                                ? "9999px 0 0 9999px"
168	                                : i === activeSegments.length - 1
169	                                ? "0 9999px 9999px 0"
170	                                : "0",
171	                          }}
172	                        />
173	                      </TooltipTrigger>
174	                      <TooltipContent side="top" className="max-w-[220px] p-3 space-y-1">
175	                        <div className="flex items-center gap-2">
176	                          <span className="inline-block w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: seg.color }} />
177	                          <span className="font-semibold text-sm">{seg.label}</span>
178	                        </div>
179	                        <p className="text-base font-bold tabular-nums">{seg.count} credits</p>
180	                        <p className="text-xs text-muted-foreground leading-relaxed">{seg.desc}</p>
181	                      </TooltipContent>
182	                    </Tooltip>
183	                  );
184	                })}
185	              </div>
186	            </div>
187	
188	            {/* Always-visible legend */}
189	            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
190	              {creditTypes.map((ct) => (
191	                <span
192	                  key={ct.key}
193	                  className={`flex items-center gap-1.5 text-xs ${ct.count > 0 ? "text-muted-foreground" : "text-muted-foreground/40"}`}
194	                >
195	                  <span
196	                    className="inline-block w-2 h-2 rounded-full shrink-0"
197	                    style={{ backgroundColor: ct.color, opacity: ct.count > 0 ? 1 : 0.3 }}
198	                  />
199	                  {ct.label} ({ct.count})
200	                </span>
201	              ))}
